```{.r .cell-code}
#== missing vals per col ==
homicide_eda %>%
  select(
    victim_racial_construct,
    temp_2m_avg,
    relative_humidity_2m_avg,
    rain_sum,
    snowfall_sum,
    agency_population,
    jurisdiction_match
  ) %>%
  summarise(
    # (Barter, 2020)
    across(
      everything(),
      ~ sum(is.na(.x))
    )
  ) %>%
  # (Olumide, 2025)
  pivot_longer(
    cols = everything(),
    names_to = "column",
    values_to = "missing"
  ) %>%
  # (Muldoon, 2021)
  gt() %>%
  tab_header(
    title = md("**Missing Values per Predictor**")
  )
