Now I'll map the county center points in two panels, one for each jurisdiction group, with each point sized by its number of records and filled by victim race, over the shifted state outlines. 

#### jurisdiction map plot


::: {.cell}

```{.r .cell-code}
# Map the county records for both jurisdiction groups in two panels.

#== two-panel map==
jurisdiction_map_plot <- ggplot() +
  #== base map ==
  geom_sf(
    data = state_map_sf,
    fill = "gray98",
    color = "gray80",
    size = 0.3
  ) +
  #== data on map ==
  geom_sf(
    data = county_points %>%
      arrange(
        desc(n)
      ),
    # (Tierney, 2025)
    aes(
      size = n,
      fill = victim_racial_construct
    ),
    shape = 21,
    color = "#275561",
    stroke = 0.2,
    alpha = 0.9
  ) +
  # (Tierney, 2025)
  scale_size_area() +
  scale_fill_manual(
    values = c(
      "Black" = "#9D5E38",
      "Not Black" = "#FFB060"
    ),
    name = "Victim race"
  ) +
  # (Tierney, 2025)
  facet_wrap(
    ~jurisdiction_match
  ) +
  labs(
    title = "Victim race within each jurisdiction group",
    subtitle = "2017 through 2020 \n\n",
    caption = "Fig.3",
    size = "Records"
  ) +
  theme_void() +
  theme() +
  ggplot_theme

